import{_ as a,o as t,c as r,a4 as o}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"Well-digging source profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/14-well-digging-profile.md","filePath":"reference/14-well-digging-profile.md","lastUpdated":1788532705000}'),i={name:"reference/14-well-digging-profile.md"};function n(d,e,s,l,c,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="well-digging-source-profile" tabindex="-1">Well-digging source profile <a class="header-anchor" href="#well-digging-source-profile" aria-label="Permalink to &quot;Well-digging source profile&quot;">​</a></h1><h2 id="authority-and-scope" tabindex="-1">Authority and scope <a class="header-anchor" href="#authority-and-scope" aria-label="Permalink to &quot;Authority and scope&quot;">​</a></h2><p>The configured election profile is based on B. V. Raman, <em>Muhurtha (Electional Astrology)</em>, Chapter XII, “Digging Wells,” printed page 51 (PDF page 55):</p><p><a href="https://www.panchanga.lv/wp-content/uploads/2020/06/Muhurta_Raman.pdf" target="_blank" rel="noreferrer">https://www.panchanga.lv/wp-content/uploads/2020/06/Muhurta_Raman.pdf</a></p><p>Raman is a modern synthesis and secondary authority, not a primary scripture. The profile selects a time to begin digging; it does not perform hydrology, site divination, engineering assessment, or water-safety certification.</p><h2 id="rule-to-code-crosswalk" tabindex="-1">Rule-to-code crosswalk <a class="header-anchor" href="#rule-to-code-crosswalk" aria-label="Permalink to &quot;Rule-to-code crosswalk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source statement</th><th>Locator</th><th>Implementation</th><th>Treatment</th></tr></thead><tbody><tr><td>Revati, Uttara Bhadrapada, Hasta, Anuradha, Magha, Shravana, Rohini and Pushya are favourable</td><td>p. 51 (PDF 55)</td><td><code>allowed_nakshatras</code></td><td>The active slot-time Nakshatra must be one of the eight named values.</td></tr><tr><td>Rising Rasi should be Meena, Karkataka or Makara</td><td>p. 51 (PDF 55)</td><td><code>allowed_lagnas</code></td><td>The active slot-time Lagna must be one of these three exact Rasis. This also excludes the specifically discouraged Kumbha and Vrisabha.</td></tr><tr><td>Beginning in the Rasi occupied by Surya causes delay from hard rock</td><td>p. 51 (PDF 55)</td><td><code>caution_lagna_solar</code></td><td>When Lagna and Surya&#39;s Rasi coincide, the result carries the source caution. It is not converted into an invented score or absolute rejection.</td></tr><tr><td>Shukra and Chandra should occupy Kendras</td><td>p. 51 (PDF 55)</td><td><code>manual_checks</code></td><td>Disclosed for practitioner review; the finder does not yet validate complete election-chart house occupancy.</td></tr><tr><td>Abundant sweet water when Chandra or Shukra is in a Kendra identical with a full watery Rasi</td><td>p. 51 (PDF 55)</td><td><code>manual_checks</code></td><td>Preserved as a source condition, not presented as a hydrological prediction or automated guarantee.</td></tr></tbody></table><h2 id="product-contract-and-limitations" tabindex="-1">Product contract and limitations <a class="header-anchor" href="#product-contract-and-limitations" aria-label="Permalink to &quot;Product contract and limitations&quot;">​</a></h2><p>This replaces the former generic “Adho Nakshatra Mukha +1” proxy for well digging. Python, MCP, and browser now use one generated activity contract; the browser selector exposes the activity directly. Every surviving result states its admitted Lagna and repeats the manual chart checks. MCP exposes the stable <code>muhurta.well_digging</code> provenance identifier and the same constraints.</p><p>Hard inauspicious windows, choghadiya contribution, Tarabalam, Chandrabalam, Panchaka and relative tiers are shared project rules. This citation does not establish them. Geological suitability, lawful permits, structural safety and water potability require qualified local professionals.</p>',10)])])}const g=a(i,[["render",n]]);export{p as __pageData,g as default};
